namespace sv_73aae8b979cd424791922705a388f3f1.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public DateTime? EstimatedDelivery { get; init; }
    public required List<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required string Description { get; init; }
    public required string Location { get; init; }
    public required DateTime Timestamp { get; init; }
}

using sv_73aae8b979cd424791922705a388f3f1.Client.Models;

namespace sv_73aae8b979cd424791922705a388f3f1.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_73aae8b979cd424791922705a388f3f1.Client.Models;

namespace sv_73aae8b979cd424791922705a388f3f1.Client.Services;

/// <summary>
/// WebAssembly-side implementation that calls the server API.
/// </summary>
public sealed class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

using sv_73aae8b979cd424791922705a388f3f1.Client.Models;
using sv_73aae8b979cd424791922705a388f3f1.Client.Services;

namespace sv_73aae8b979cd424791922705a388f3f1.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Memphis, TN",
            EstimatedDelivery = new DateTime(2026, 6, 21, 17, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Los Angeles, CA", Timestamp = new DateTime(2026, 6, 15, 9, 30, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Departed facility", Location = "Los Angeles, CA", Timestamp = new DateTime(2026, 6, 15, 14, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at hub", Location = "Memphis, TN", Timestamp = new DateTime(2026, 6, 16, 6, 45, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "In transit to destination", Location = "Memphis, TN", Timestamp = new DateTime(2026, 6, 17, 8, 0, 0, DateTimeKind.Utc) },
            ]
        },
        ["TRK-2002"] = new Shipment
        {
            TrackingNumber = "TRK-2002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTime(2026, 6, 16, 12, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Chicago, IL", Timestamp = new DateTime(2026, 6, 13, 10, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "In transit", Location = "Columbus, OH", Timestamp = new DateTime(2026, 6, 14, 3, 15, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Out for delivery", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 16, 7, 30, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Delivered — signed by J. Smith", Location = "New York, NY", Timestamp = new DateTime(2026, 6, 16, 11, 22, 0, DateTimeKind.Utc) },
            ]
        },
        ["TRK-3003"] = new Shipment
        {
            TrackingNumber = "TRK-3003",
            Status = "Out for Delivery",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTime(2026, 6, 18, 18, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Location = "Portland, OR", Timestamp = new DateTime(2026, 6, 16, 15, 0, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Arrived at local facility", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 17, 22, 10, 0, DateTimeKind.Utc) },
                new StatusUpdate { Description = "Out for delivery", Location = "Seattle, WA", Timestamp = new DateTime(2026, 6, 18, 6, 45, 0, DateTimeKind.Utc) },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_73aae8b979cd424791922705a388f3f1.Client.Models
@using sv_73aae8b979cd424791922705a388f3f1.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<Shipments> Logger
@implements IDisposable

<PageTitle>Track Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracking</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment details for <strong>@TrackingNumber</strong>…
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p class="mb-1"><strong>Status:</strong> @_shipment.Status</p>
            <p class="mb-1"><strong>Location:</strong> @_shipment.Location</p>
            @if (_shipment.EstimatedDelivery.HasValue)
            {
                <p class="mb-0"><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h5>Tracking History</h5>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override async Task OnParametersSetAsync()
    {
        // Skip if we already loaded this tracking number.
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase) && !_loading)
            return;

        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request.
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }

        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _loading = true;
        _errorMessage = null;
        _shipment = null;
        _loadedTrackingNumber = TrackingNumber;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigated away or disposed — nothing to show.
            return;
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        _loadedTrackingNumber = null;
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

